describe('req.parseBody()', async () => {
  it('should parse form data', async () => {
    const data = new FormData()
    data.append('foo', 'bar')
    const req = new HonoRequest(
      new Request('http://localhost', {
        method: 'POST',
        body: data,
      })
    )
    expect((await req.parseBody())['foo']).toBe('bar')
    expect(async () => await req.text()).not.toThrow()
    expect(async () => await req.arrayBuffer()).not.toThrow()
    expect(async () => await req.bytes()).not.toThrow()
    expect(async () => await req.blob()).not.toThrow()
  })

  describe('should not break body methods after parseBody() with non-form content-type', () => {
    const createReq = () =>
      new HonoRequest(
        new Request('http://localhost', {
          method: 'POST',
          body: JSON.stringify({ event: 'push' }),
          headers: { 'Content-Type': 'application/json' },
        })
      )

    it('text()', async () => {
      const req = createReq()
      await req.parseBody()
      expect(await req.text()).toBe(JSON.stringify({ event: 'push' }))
    })

    it('json()', async () => {
      const req = createReq()
      await req.parseBody()
      expect(await req.json()).toEqual({ event: 'push' })
    })

    it('arrayBuffer()', async () => {
      const req = createReq()
      await req.parseBody()
      expect(await req.arrayBuffer()).toBeInstanceOf(ArrayBuffer)
    })

    it('bytes()', async () => {
      const req = createReq()
      await req.parseBody()
      expect(await req.bytes()).toBeInstanceOf(Uint8Array)
    })

    it('blob()', async () => {
      const req = createReq()
      await req.parseBody()
      expect(await req.blob()).toBeInstanceOf(Blob)
    })

    it('formData()', async () => {
      const req = createReq()
      await req.parseBody()
      // application/json is not a valid formData content-type, so this should throw
      expect(req.formData()).rejects.toThrow()
    })
  })

  describe('Return type', () => {
    let req: HonoRequest
    beforeEach(() => {

      // `c.req.blob()` should not throw the error
      await c.req.blob()
      return c.text('foo')
    }
  )

  it('Should not throw the error with c.req.json()', async () => {
    const req = new Request('http://localhost', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ foo: 'bar' }),
    })
    const res = await app.request(req)
    expect(res.status).toBe(200)
  })
})

describe('form', () => {
  const app = new Hono()
  app.post(
    '/',
    validator('form', () => {
      return {
        foo: 'bar',
      }
    }),
    async (c) => {
      // `c.req.parseBody()` should not throw the error
      await c.req.parseBody()
      // `c.req.text()` should not throw the error
      await c.req.text()
      // `c.req.arrayBuffer()` should not throw the error
      await c.req.arrayBuffer()
      // `c.req.blob()` should not throw the error
      await c.req.blob()
      return c.text('foo')
    }
  )

  app.post(
    '/cached',
    async (c, next) => {
      await c.req.parseBody()
      await next()
    },
    validator('form', (value) => {
      if (value instanceof FormData) {
        throw new Error('The value should not be a FormData')
      }
      return value
    }),
    (c) => {
      const v = c.req.valid('form')
      return c.json(v)
    }
  )

  it('Should not throw the error with c.req.parseBody()', async () => {
    const body = new FormData()
    body.append('foo', 'bar')
    const req = new Request('http://localhost', {
      method: 'POST',
      body: body,
    })
    const res = await app.request(req)
    expect(res.status).toBe(200)
  })

  it('Should not be an instance of FormData if the formData is cached', async () => {
    const body = new FormData()
    body.append('foo', 'bar')
    const req = new Request('http://localhost/cached', {
      method: 'POST',
      body: body,
    })
    const res = await app.request(req)
    expect(res.status).toBe(200)
    expect(await res.json()).toEqual({ foo: 'bar' })

