import { HonoRequest } from '../clone/src/request'
import { parseBody } from '../clone/src/utils/body'

const log = (label: string, v: unknown) => console.log(label, '=>', v)

async function run(label: string, fn: () => Promise<unknown>) {
  try {
    log(label, JSON.stringify(await fn()))
  } catch (e) {
    log(label, `THROWS ${(e as Error).constructor.name}: ${(e as Error).message}`)
  }
}

const multipartReq = () => {
  const fd = new FormData()
  fd.append('message', 'hello')
  return new Request('http://localhost/post', { method: 'POST', body: fd })
}
const urlencodedReq = () => {
  const p = new URLSearchParams()
  p.append('message', 'hello')
  return new Request('http://localhost/post', {
    method: 'POST',
    body: p,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  })
}

// Scenario A: c.req.formData() then c.req.parseBody() (multipart)
await run('A multipart: formData() then parseBody()', async () => {
  const req = new HonoRequest(multipartReq())
  await req.formData()
  return await req.parseBody()
})

// Scenario B: same, urlencoded
await run('B urlencoded: formData() then parseBody()', async () => {
  const req = new HonoRequest(urlencodedReq())
  await req.formData()
  return await req.parseBody()
})

// Scenario C: parseBody() twice
await run('C multipart: parseBody() twice', async () => {
  const req = new HonoRequest(multipartReq())
  await req.parseBody()
  return await req.parseBody()
})

// Scenario D: parseBody() then formData()
await run('D multipart: parseBody() then formData()', async () => {
  const req = new HonoRequest(multipartReq())
  await req.parseBody()
  return (await req.formData()).get('message')
})

// Scenario E: text() then parseBody()
await run('E multipart: text() then parseBody()', async () => {
  const req = new HonoRequest(multipartReq())
  await req.text()
  return await req.parseBody()
})

// Scenario F: blob() then parseBody()
await run('F multipart: blob() then parseBody()', async () => {
  const req = new HonoRequest(multipartReq())
  await req.blob()
  return await req.parseBody()
})

// Scenario G: parseBody() then text() — does the text match the original bytes?
await run('G multipart: parseBody() then text() equals original', async () => {
  const raw = multipartReq()
  const original = await raw.clone().text()
  const req = new HonoRequest(raw)
  await req.parseBody()
  return (await req.text()) === original
})

// Scenario H: via middleware in an app: middleware calls c.req.formData(), handler calls parseBody()
await run('H app: middleware formData() then handler parseBody()', async () => {
  const app = new Hono()
  app.use(async (c, next) => {
    await c.req.formData()
    await next()
  })
  app.post('/post', async (c) => c.json(await c.req.parseBody()))
  const res = await app.request(multipartReq())
  return { status: res.status, body: await res.text() }
})

// Scenario I: plain Request, formData() then parseBody (never worked, body used)
await run('I plain Request: formData() then parseBody()', async () => {
  const req = multipartReq()
  await req.formData()
  return await parseBody(req)
})

// Scenario J: parseBody on plain Request with mixed-case multipart (new behaviour)
await run('J plain Request: mixed-case multipart', async () => {
  const src = multipartReq()
  const ct = src.headers.get('Content-Type')!.replace('multipart/form-data', 'MULTIPART/FORM-DATA')
  const req = new Request('http://localhost/post', {
    method: 'POST',
    body: await src.arrayBuffer(),
    headers: { 'Content-Type': ct },
  })
  return await parseBody(req)
})

// Scenario K: parseBody with bogus `multipart/form-data-x` (startsWith used to match)
await run('K plain Request: multipart/form-datax (startsWith previously matched)', async () => {
  const req = new Request('http://localhost/post', {
    method: 'POST',
    body: 'a=b',
    headers: { 'Content-Type': 'application/x-www-form-urlencodedx' },
  })
  return await parseBody(req)
})

